import React, { useState } from 'react';
import { Container, TextField, Button, Typography, Box, IconButton, InputAdornment, CircularProgress } from '@mui/material';
import { Visibility, VisibilityOff } from '@mui/icons-material';
import { useAuth } from './AuthContext';

const LoginPage = () => {
    const [showPassword, setShowPassword] = useState(false);
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const { login } = useAuth();

    const togglePasswordVisibility = () => {
        setShowPassword((prev) => !prev);
    };

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        try {
            const response = await fetch('http://localhost:8080/worker/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ username, password }),
            });

            const data = await response.json();

            if (response.ok) {
                // Create a user object with all needed data
                const userData = {
                    username: data.username,
                    firstName: data.firstName,
                    lastName: data.lastName,
                    isAdmin: data.isAdmin,
                    workerID: data.workerID
                };

                // Call the login function from AuthContext
                login(userData);
            } else {
                setError(data.message || 'Invalid username or password');
            }
        } catch (error) {
            setError('Error connecting to server. Please try again later.');
            console.error('Connection error:', error);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Container maxWidth="xs" sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <Typography variant="h3" align="center" gutterBottom sx={{ fontWeight: 'bold', mt: 4 }}>
                Steve Ball & Associates
            </Typography>
            <Box 
                component="form" 
                onSubmit={handleLogin}
                sx={{ mt: 2, p: 4, boxShadow: 3, borderRadius: 2, width: '100%' }}
            >
                <Typography variant="h4" gutterBottom align="center">Login</Typography>

                {error && (
                    <Typography color="error" sx={{ mb: 2 }}>
                        {error}
                    </Typography>
                )}

                <TextField
                    label="Username"
                    variant="outlined"
                    fullWidth
                    margin="normal"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    required
                    autoFocus
                    inputProps={{ 'data-testid': 'username-input' }}
                />

                <TextField
                    label="Password"
                    type={showPassword ? "text" : "password"}
                    variant="outlined"
                    fullWidth
                    margin="normal"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    InputProps={{
                        endAdornment: (
                            <InputAdornment position="end">
                                <IconButton 
                                    onClick={togglePasswordVisibility} 
                                    edge="end"
                                    aria-label={showPassword ? "hide password" : "show password"}
                                >
                                    {showPassword ? <VisibilityOff /> : <Visibility />}
                                </IconButton>
                            </InputAdornment>
                        ),
                        'data-testid': 'password-input'
                    }}
                />

                <Button
                    type="submit"
                    variant="contained"
                    color="primary"
                    fullWidth
                    sx={{ mt: 2 }}
                    disabled={isLoading || !username || !password}
                >
                    {isLoading ? <CircularProgress size={24} /> : 'Login'}
                </Button>
            </Box>
        </Container>
    );
};

export default LoginPage;
